def maxPairSumByDigitSum(nums):
    best = {}
    ans = -1
    for x in nums:
        s = 0
        y = x
        while y:
            s += y % 10
            y //= 10
        if s in best:
            ans = max(ans, best[s] + x)
            if x > best[s]:
                best[s] = x
        else:
            best[s] = x
    return ans
